def build() -> None:
    out = Path(__file__).resolve().parents[1] / "config" / "i18n"
    out.mkdir(parents=True, exist_ok=True)
    for i, code in enumerate(LANGS):
        strings = {row[0]: row[i + 1] for row in T}
        js = {k: v[i] for k, v in JS.items()}
        (out / f"{code}.json").write_text(json.dumps({"_note": "Generated by tools/i18n_catalog.py; edit there.",
                                                      "strings": strings, "js": js}, ensure_ascii=False, indent=1) + "\n",
                                          encoding="utf-8")
    print(f"wrote {len(LANGS)} catalogs, {len(T)} strings each")


if __name__ == "__main__":
    build()
